package com.fitnutri.backend.summary;

import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import static org.junit.jupiter.api.Assertions.*;

class SummaryIntegrationTest extends PostgresIntegrationSupport {
    @Autowired SummaryService summaries;@Autowired UserRepository users;@Autowired ProfileService profileService;@Autowired UserProfileRepository profiles;@Autowired WeightEntryRepository weights;@Autowired FoodDatasetRepository foodDatasets;@Autowired FoodReferenceRepository references;@Autowired ActivityDatasetRepository activityDatasets;@Autowired ExerciseTypeRepository types;@Autowired FoodRecordRepository foods;@Autowired ExerciseRecordRepository exercises;@Autowired FoodRecordService foodService;@Autowired ExerciseRecordService exerciseService;@Autowired ExerciseEstimateService estimates;@Autowired RecordReadService reads;
    private RecordFixtureFactory fixtures;
    @BeforeEach void fixtures(){fixtures=new RecordFixtureFactory(users,profileService,foodDatasets,references,activityDatasets,types);}
    private LocalDate day(int day){return LocalDate.of(2020,1,day);}
    private BigDecimal decimal(String value){return value==null?null:new BigDecimal(value);}
    private FoodRecord food(User owner,LocalDate day,String energy,String protein,String fat,String carbs){var r=new FoodRecord();r.setUser(owner);r.setFoodName("Synthetic legacy summary fixture");r.setSource(RecordSource.PHOTO);r.setRecordDate(day);r.setRecordedAt(Instant.parse("2026-10-16T10:00:00Z"));r.setClientEntryId(UUID.randomUUID());r.setQuantityGramsSnapshot(new BigDecimal("100.000"));r.setMealType(MealType.LUNCH);r.setEnergyKj(decimal(energy));r.setProteinGramsSnapshot(decimal(protein));r.setFatGramsSnapshot(decimal(fat));r.setCarbsGramsSnapshot(decimal(carbs));r.setCalories(999.0);return foods.saveAndFlush(r);}
    private ExerciseRecord exercise(User owner,LocalDate day,String energy,String minutes){var r=new ExerciseRecord();r.setUser(owner);r.setExerciseType("Synthetic legacy activity");r.setSource(RecordSource.MANUAL);r.setRecordDate(day);r.setRecordedAt(Instant.parse("2026-10-16T10:00:00Z"));r.setClientEntryId(UUID.randomUUID());r.setDurationMinutes(new BigDecimal(minutes));r.setEstimatedKj(decimal(energy));r.setEstimatedCalories(777.0);return exercises.saveAndFlush(r);}
    private void threeDays(User owner){food(owner,day(1),"100",null,"5","20");food(owner,day(2),null,"10",null,null);food(owner,day(3),"0",null,"0",null);exercise(owner,day(1),null,"10.50");exercise(owner,day(2),"0","20.00");}
    @Test void actualGroupedHundredNullZeroUseIndependentKnownDayAveragesAndHonestLegacyCounts(){var u=fixtures.owner();threeDays(u);var result=summaries.period(u.getId(),day(1),day(3),null);assertEquals(new BigDecimal("100.000"),result.totals().intake().knownSum());assertEquals(3,result.totals().intake().recordCount());assertEquals(2,result.totals().intake().knownValueCount());assertEquals(1,result.totals().intake().missingValueCount());assertEquals(2,result.totals().intake().legacyValueCount());assertTrue(result.totals().intake().partial());assertEquals(new BigDecimal("50.000"),result.averages().intake().value());assertEquals(2,result.averages().intake().knownDayCount());assertEquals(new BigDecimal("10.000"),result.averages().protein().value());assertEquals(1,result.averages().protein().knownDayCount());assertEquals(new BigDecimal("2.500"),result.averages().fat().value());assertEquals(2,result.averages().fat().knownDayCount());assertEquals(new BigDecimal("0.000"),result.averages().expenditure().value());assertEquals(1,result.averages().expenditure().knownDayCount());assertEquals(new BigDecimal("30.50"),result.totals().activityMinutes());assertEquals(new BigDecimal("15.250"),result.averages().activityMinutes().value());assertNull(result.days().get(1).intake().knownSum());assertEquals(new BigDecimal("0.000"),result.days().get(2).intake().knownSum());}
    @Test void noProfileTargetNeverFallsBackAndExplicitCurrentTargetOnlyUsesKnownDates(){var u=fixtures.owner();threeDays(u);var p=profiles.findById(u.getId()).orElseThrow();p.setGoal(Goal.LOSE_FAT);profiles.saveAndFlush(p);assertNull(summaries.period(u.getId(),day(1),day(3),null).goalComparison());p=profiles.findById(u.getId()).orElseThrow();p.setDailyTargetKj(new BigDecimal("8400.000"));profiles.saveAndFlush(p);var goal=summaries.period(u.getId(),day(1),day(3),null).goalComparison();assertEquals(new BigDecimal("8400.000"),goal.dailyTargetKj());assertEquals(2,goal.comparedDays());assertEquals(new BigDecimal("16800.000"),goal.targetForComparedDaysKj());assertEquals(new BigDecimal("100.000"),goal.knownIntakeKj());}
    @Test void ownerDateAndSoftDeleteFiltersMatchCanonicalHistoryDespiteUnrelatedCreationTime(){var u=fixtures.owner();var other=fixtures.owner();threeDays(u);food(other,day(1),"999999",null,null,null);exercise(other,day(1),"999999","100");var deleted=food(u,day(2),"1000",null,null,null);deleted.setDeletedAt(Instant.now());foods.saveAndFlush(deleted);var period=summaries.period(u.getId(),day(1),day(3),"Australia/Sydney");var list=reads.listFoods(u.getId(),day(1),day(3),null,null);assertEquals(3,list.size());assertEquals(list.size(),period.totals().foodCount());var known=list.stream().map(r->r.nutrients().energyKj()).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);assertEquals(known,period.totals().intake().knownSum());assertEquals(2,period.totals().exerciseCount());assertEquals(new BigDecimal("100.000"),period.totals().intake().knownSum());assertEquals(period,summaries.period(u.getId(),day(1),day(3),"UTC"));}
    @Test void correctionDateMovementAndSoftDeleteChangeEveryAggregateFromTheSameSavedRows(){var u=fixtures.owner();var f=fixtures.food("100");var t=fixtures.exercise("3.5");var foodInput=new FoodBatchRequest(UUID.randomUUID(),day(2),"Australia/Sydney",RecordSource.MANUAL,List.of(new FoodBatchRequest.Item(UUID.randomUUID(),f.getId().toString(),new BigDecimal("100"),MealType.LUNCH)));var fp=foodService.confirmBatch(u.getId(),foodInput);Long foodId=Long.valueOf(fp.records().getFirst().id());var initial=estimates.estimate(u.getId(),t.getId(),day(2),BigDecimal.TEN,"Australia/Sydney");var ep=exerciseService.confirmExercise(u.getId(),new CreateExerciseRecordRequest(UUID.randomUUID(),day(2),"Australia/Sydney",RecordSource.MANUAL,t.getId().toString(),BigDecimal.TEN,UUID.randomUUID(),initial.calculationFingerprint()));Long exerciseId=Long.valueOf(ep.records().getFirst().id());assertEquals(new BigDecimal("100.000"),summaries.daily(u.getId(),day(2),null).day().intake().knownSum());foodService.updateOwned(u.getId(),foodId,new UpdateFoodRecordRequest(0L,f.getId().toString(),new BigDecimal("150"),MealType.DINNER,day(3),"Australia/Sydney"));var preview=estimates.estimate(u.getId(),t.getId(),day(3),BigDecimal.TEN,"Australia/Sydney");exerciseService.updateOwned(u.getId(),exerciseId,new UpdateExerciseRecordRequest(0L,t.getId().toString(),BigDecimal.TEN,day(3),"Australia/Sydney",preview.calculationFingerprint()));assertEquals(0,summaries.daily(u.getId(),day(2),null).day().foodCount());assertEquals(0,summaries.daily(u.getId(),day(2),null).day().exerciseCount());var moved=summaries.daily(u.getId(),day(3),null);assertEquals(new BigDecimal("150.000"),moved.day().intake().knownSum());assertEquals(new BigDecimal("170.847"),moved.day().expenditure().knownSum());foodService.softDeleteOwned(u.getId(),foodId,1L);exerciseService.softDeleteOwned(u.getId(),exerciseId,1L);var empty=summaries.period(u.getId(),day(1),day(3),null);assertNull(empty.totals().intake().knownSum());assertNull(empty.totals().expenditure().knownSum());assertNull(empty.totals().activityMinutes());assertEquals(0,empty.totals().foodCount());assertEquals(0,empty.totals().exerciseCount());}
    @Test void weeklyUsesActualEndAndPreviousEqualLengthRangeWithRecomputableFacts(){var u=fixtures.owner();food(u,day(1),"100",null,null,null);food(u,day(3),"0",null,null,null);food(u,LocalDate.of(2019,12,31),"200",null,null,null);var result=summaries.weekly(u.getId(),day(7),null);assertEquals(day(1),result.current().rangeStart());assertEquals(day(7),result.current().rangeEnd());assertEquals(7,result.current().calendarDayCount());assertEquals(LocalDate.of(2019,12,25),result.previous().rangeStart());assertEquals(LocalDate.of(2019,12,31),result.previous().rangeEnd());var difference=result.current().facts().stream().filter(f->f.code().equals("INTAKE_AVERAGE_CHANGE")).findFirst().orElseThrow();assertEquals(new BigDecimal("-150.000"),difference.values().get("difference"));assertEquals(2,difference.values().get("currentKnownDayCount"));assertEquals(1,difference.values().get("previousKnownDayCount"));}
    @Test void weightFactUsesOnlyRecordedDatesInSelectedRangeAndRetainsExactDecimalChange(){var u=fixtures.owner();weights.saveAndFlush(WeightEntry.of(u,new BigDecimal("71.25"),day(3)));var period=summaries.period(u.getId(),day(1),day(3),null);var fact=period.facts().stream().filter(f->f.code().equals("RECORDED_WEIGHT_CHANGE")).findFirst().orElseThrow();assertEquals(new BigDecimal("1.25"),fact.values().get("changeKg"));assertEquals("2020-01-01",fact.values().get("fromDate"));assertTrue(fact.text().contains("+1.3 kg"));assertTrue(summaries.period(u.getId(),day(2),day(3),null).facts().stream().anyMatch(f->f.code().equals("INSUFFICIENT_WEIGHT_CHANGE_DATA")));}
    @Test void emptyRangesAndMissingValuesNeverBecomeMeasurementsAndAmbiguousShortcutIs400(){var u=fixtures.owner();var period=summaries.period(u.getId(),day(1),day(3),null);assertEquals(3,period.days().size());assertFalse(period.totals().intake().hasData());assertNull(period.totals().intake().knownSum());assertEquals(0,period.averages().intake().knownDayCount());assertTrue(period.days().stream().allMatch(d->d.intake().knownSum()==null));assertThrows(BusinessException.class,()->summaries.trends(u.getId(),day(1),day(3),7,null));assertThrows(BusinessException.class,()->summaries.period(u.getId(),day(3),day(1),null));assertEquals(366,summaries.trends(u.getId(),null,null,366,null).calendarDayCount());}
    @Test void allMissingRecordedDayAndNoRecordDayHaveDifferentFlags(){var u=fixtures.owner();food(u,day(1),null,null,null,null);var missing=summaries.daily(u.getId(),day(1),null).day().intake();var absent=summaries.daily(u.getId(),day(2),null).day().intake();assertTrue(missing.hasData());assertEquals(1,missing.recordCount());assertEquals(1,missing.missingValueCount());assertNull(missing.knownSum());assertFalse(absent.hasData());assertEquals(0,absent.recordCount());assertNull(absent.knownSum());}
    @Test void actualCurrentZeroReferenceRemainsKnownAndIsNotLabeledLegacy(){var u=fixtures.owner();var f=fixtures.food("0");foodService.confirmBatch(u.getId(),new FoodBatchRequest(UUID.randomUUID(),day(2),"Australia/Sydney",RecordSource.MANUAL,List.of(new FoodBatchRequest.Item(UUID.randomUUID(),f.getId().toString(),new BigDecimal("100"),MealType.LUNCH))));var metric=summaries.daily(u.getId(),day(2),null).day().intake();assertTrue(metric.hasData());assertEquals(new BigDecimal("0.000"),metric.knownSum());assertEquals(1,metric.knownValueCount());assertEquals(0,metric.missingValueCount());assertEquals(0,metric.legacyValueCount());assertFalse(metric.partial());}
}
